import fs from 'node:fs';
import path from 'node:path';
import assert from 'node:assert/strict';
import { fileURLToPath } from 'node:url';
// Compile the JavaScript fragments generated by EJS, even when npm dependencies
// are unavailable. This does not replace an EJS render test; it catches unclosed
// EJS delimiters and syntactically invalid embedded JavaScript.
import vm from 'node:vm';
function assertEjsDelimitersAndJavaScript(source, filename) {
  let pos = 0;
  let compiled = 'const __out = [];\n';
  for (;;) {
    const open = source.indexOf('<%', pos);
    if (open === -1) break;
    const close = source.indexOf('%>', open + 2);
    assert.ok(close >= 0, `Unclosed EJS tag in ${filename}, line ${source.slice(0, open).split('\n').length}`);
    const nested = source.indexOf('<%', open + 2);
    assert.ok(nested < 0 || nested > close, `Nested or unclosed EJS tag in ${filename}, line ${source.slice(0, open).split('\n').length}`);
    const code = source.slice(open + 2, close);
    if (code.startsWith('=') || code.startsWith('-')) compiled += `__out.push((${code.slice(1)}));\n`;
    else if (!code.startsWith('#')) compiled += `${code}\n`;
    pos = close + 2;
  }
  assert.doesNotMatch(source.slice(pos), /%>/, `Unexpected EJS closing delimiter in ${filename}`);
  assert.doesNotThrow(() => new vm.Script(`(function(){\n${compiled}\n})`, {filename}), `Invalid embedded EJS JavaScript in ${filename}`);
}

const root=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const files=[];
function walk(dir){ for(const name of fs.readdirSync(dir)){ const p=path.join(dir,name),st=fs.statSync(p); if(st.isDirectory()) walk(p); else if(name.endsWith('.ejs')) files.push(p); } }
walk(path.join(root,'views'));
for(const file of files){
  const source=fs.readFileSync(file,'utf8');
  assertEjsDelimitersAndJavaScript(source, path.relative(root,file));
  const forms=[...source.matchAll(/<form\b[\s\S]*?<\/form>/gi)].map(m=>m[0]);
  for(const form of forms){
    const method=form.match(/\bmethod=["']post["']/i);
    if(method) assert.ok(/name=["']_csrf["']/i.test(form) || /x-csrf-token/i.test(form),`POST form missing CSRF field in ${path.relative(root,file)}`);
  }
  for(const m of source.matchAll(/<script\b[^>]*src=["']([^"']+)["']/gi)) assert.ok(m[1].startsWith('/') || m[1].startsWith('https://'),`Unexpected script source in ${path.relative(root,file)}`);
  for(const m of source.matchAll(/target=["']_blank["'][^>]*>/gi)) assert.ok(/rel=["'][^"']*noopener/i.test(m[0]),`_blank link missing noopener in ${path.relative(root,file)}`);
}
console.log(`Template audit passed: ${files.length} EJS templates inspected.`);
